import json, urllib.request, urllib.parse, re, time

def cr_search(title):
    url = 'https://api.crossref.org/works?rows=4&query.bibliographic=' + urllib.parse.quote(title)
    req = urllib.request.Request(url, headers={'User-Agent': 'redteam/1.0 (mailto:timzhao@stanford.edu)'})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read().decode())['message']['items']

def s2(doi):
    url = 'https://api.semanticscholar.org/graph/v1/paper/DOI:' + urllib.parse.quote(doi) + '?fields=title,abstract,year,venue'
    req = urllib.request.Request(url, headers={'User-Agent': 'redteam/1.0'})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return json.loads(r.read().decode())
    except Exception as e:
        return {'error': str(e)[:100]}

def deinvert(inv):
    if not inv: return None
    pos = {}
    for w, idxs in inv.items():
        for i in idxs: pos[i] = w
    return ' '.join(pos[i] for i in sorted(pos))

def oa(doi):
    url = 'https://api.openalex.org/works/https://doi.org/' + urllib.parse.quote(doi)
    req = urllib.request.Request(url, headers={'User-Agent': 'redteam/1.0 (mailto:timzhao@stanford.edu)'})
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            m = json.loads(r.read().decode())
        return deinvert(m.get('abstract_inverted_index'))
    except Exception as e:
        return 'ERR ' + str(e)[:80]

for t in ['Final design of the ITER outer vessel steady-state magnetic sensors',
          'Calibration of the ITER outer vessel steady-state magnetic sensors',
          'Status of steady-state magnetic diagnostic for ITER and outlook for possible materials of Hall sensors for DEMO']:
    print('='*30); print('QUERY:', t)
    for it in cr_search(t)[:2]:
        ti = (it.get('title') or [''])[0]
        doi = it.get('DOI')
        yr = None
        for k in ('published-print','published-online','issued'):
            if it.get(k) and it[k].get('date-parts'): yr = it[k]['date-parts'][0][0]; break
        auth = ', '.join(a.get('family','') for a in it.get('author', [])[:6])
        ven = (it.get('container-title') or [''])[0]
        print('->', ti, '|', yr, '|', ven, '|', doi, '|', auth)
        if ti.lower().startswith(t.lower()[:40]):
            m = s2(doi)
            ab = m.get('abstract') or oa(doi)
            print('ABSTRACT:', (ab or '(none)')[:1200])
    time.sleep(0.5)
"

